-- APPLICATION tables: everything the pilot itself owns.
-- Written in plain, portable SQL so it needs only light edits for another engine
-- (e.g. on SQL Server: BOOLEAN -> BIT, "GENERATED BY DEFAULT AS IDENTITY" -> IDENTITY(1,1)).

-- Accounts: 1 administrator + sales agents.
CREATE TABLE app_user (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username       VARCHAR(50)  NOT NULL UNIQUE,
    password_hash  VARCHAR(100) NOT NULL,
    full_name      VARCHAR(100) NOT NULL,
    role           VARCHAR(10)  NOT NULL CHECK (role IN ('ADMIN', 'AGENT')),
    active         BOOLEAN      NOT NULL DEFAULT TRUE
);

-- Our copy of the source products, plus the discount set in the web panel.
CREATE TABLE product (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code              VARCHAR(30)    NOT NULL UNIQUE,
    name              VARCHAR(150)   NOT NULL,
    price             NUMERIC(12, 2) NOT NULL,
    stock             NUMERIC(12, 2) NOT NULL,
    discount_percent  NUMERIC(5, 2)  NOT NULL DEFAULT 0 CHECK (discount_percent >= 0 AND discount_percent <= 100),
    active            BOOLEAN        NOT NULL DEFAULT TRUE,
    synced_at         TIMESTAMP      NOT NULL
);

-- Our copy of the source customers.
CREATE TABLE customer (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    code       VARCHAR(30)  NOT NULL UNIQUE,
    name       VARCHAR(150) NOT NULL,
    address    VARCHAR(250),
    active     BOOLEAN      NOT NULL DEFAULT TRUE,
    synced_at  TIMESTAMP    NOT NULL
);

-- Which customers an agent visits on a given day, and in what order.
CREATE TABLE visit_assignment (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    agent_id     BIGINT  NOT NULL REFERENCES app_user (id),
    customer_id  BIGINT  NOT NULL REFERENCES customer (id),
    visit_date   DATE    NOT NULL,
    visit_order  INTEGER NOT NULL,
    CONSTRAINT uq_visit_agent_customer_day UNIQUE (agent_id, customer_id, visit_date)
);

CREATE INDEX ix_visit_agent_day ON visit_assignment (agent_id, visit_date);

-- Order header.
-- client_request_id is generated on the phone once per order; the UNIQUE constraint
-- is what stops a repeated tap or a retry from saving the same order twice.
CREATE TABLE sales_order (
    id                 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_number       VARCHAR(20)    NOT NULL UNIQUE,
    client_request_id  VARCHAR(36)    NOT NULL UNIQUE,
    customer_id        BIGINT         NOT NULL REFERENCES customer (id),
    agent_id           BIGINT         NOT NULL REFERENCES app_user (id),
    created_at         TIMESTAMP      NOT NULL,
    total              NUMERIC(14, 2) NOT NULL,
    status             VARCHAR(10)    NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING', 'APPROVED')),
    approved_at        TIMESTAMP,
    approved_by        BIGINT REFERENCES app_user (id)
);

CREATE INDEX ix_order_agent ON sales_order (agent_id, created_at);

-- Order lines.
-- Name, price and discount are COPIED here when the order is saved, so later price
-- changes never alter an order that was already registered.
CREATE TABLE sales_order_line (
    id                BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    order_id          BIGINT         NOT NULL REFERENCES sales_order (id),
    line_no           INTEGER        NOT NULL,
    product_id        BIGINT         NOT NULL REFERENCES product (id),
    product_code      VARCHAR(30)    NOT NULL,
    product_name      VARCHAR(150)   NOT NULL,
    quantity          NUMERIC(12, 2) NOT NULL CHECK (quantity > 0),
    unit_price        NUMERIC(12, 2) NOT NULL,
    discount_percent  NUMERIC(5, 2)  NOT NULL DEFAULT 0,
    line_total        NUMERIC(14, 2) NOT NULL,
    CONSTRAINT uq_order_line UNIQUE (order_id, line_no)
);
